*---------------------------------------------------------------
* COBRT -- our runtime. Nothing here is from SYS1.COBLIB.
* DISPLAY reaches SYSOUT through QSAM directly, which is the
* same access-method path IKFCBL00 uses for its own file I/O.
* Not reentrant: MVS 3.8j batch does not require it.
*---------------------------------------------------------------
COBRT    CSECT
         ENTRY COBDISP,COBTERM,COBWRL,COBDATE,COBACC,COBUPSI,COBADV
*
* COBDISP -- write one line to SYSOUT.
*   R1 -> A(text), A(halfword length).  Opens SYSOUT on demand.
*
COBDISP  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE1+4
         LA    11,RTSAVE1
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(text)
         L     3,4(0,1)            A(length)
         LH    4,0(0,3)            length
         CLI   RTOPEN,X'01'        already open?
         BE    COBD010
         OPEN  (RTDCB,OUTPUT)
         MVI   RTOPEN,X'01'
COBD010  MVI   RTLINE,C' '         ASA: single space
         MVC   RTLINE+1(120),RTLINE  blank the text area
         LTR   4,4
         BNP   COBD020             empty: emit a blank line
         CH    4,RTMAX
         BNH   COBD015
         LH    4,RTMAX             truncate at line width
COBD015  BCTR  4,0                 EX wants length-1
         EX    4,COBDMVC
COBD020  PUT   RTDCB,RTLINE
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
COBDMVC  MVC   RTLINE+1(0),0(2)    executed, never fallen into
*
* COBADV -- write one line with ASA carriage control.
*
*   R1 -> A(dcb), A(print buffer), A(halfword record length),
*         A(halfword owed), A(halfword request)
*
* ASA says what to do BEFORE a line prints, which is exactly
* what AFTER ADVANCING means. BEFORE has to be held over: the
* line goes out with whatever was owed from the last BEFORE,
* and its own count becomes what the next line owes. Once the
* two can add up the total is not known until run time, which
* is why this is a routine and not a few instructions inline.
*
* The request is the line count, or -1 for PAGE, negated when
* the phrase was BEFORE.
COBADV   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE7+4
         LA    11,RTSAVE7
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(dcb)
         L     3,4(0,1)            A(buffer)
         L     4,8(0,1)            A(length)
         L     5,12(0,1)           A(owed)
         L     6,16(0,1)           A(request)
         LH    7,0(0,4)            the record length
         LTR   7,7
         LH    8,0(0,6)            the request
         LH    9,0(0,5)            what the last BEFORE left owing
         LTR   8,8                 BEFORE is the negative side
         BM    ADV100
         CH    8,ADVPAGE           AFTER PAGE?
         BE    ADV020
         CH    9,ADVPAGE           was a page already owed?
         BE    ADV030              then it stays a page, whatever this
         AR    9,8                 owed plus this one
         B     ADV030
ADV020   LH    9,ADVPAGE           a page skip swallows what was owed
ADV030   XC    0(2,5),0(5)         nothing owed after an AFTER
         B     ADV200
ADV100   LCR   8,8                 back to a positive request
         CH    8,ADVPAGE           BEFORE PAGE?
         BNE   ADV110
         LH    8,ADVPAGE
ADV110   STH   8,0(0,5)            this is what the next line owes
         LTR   9,9                 nothing owed?
         BNZ   ADV200
         LH    9,ADVONE            then this line simply takes the next
ADV200   CH    9,ADVPAGE           a page skip?
         BNE   ADV210
         MVI   0(3),C'1'           skip to a new page
         B     ADV300
ADV210   LTR   9,9
         BNM   ADV220
         SR    9,9                 never negative here
ADV220   CH    9,ADVTHREE          more than one code can carry?
         BNH   ADV240
         PUT   (2),ADVB3           three blank lines at a time
         SH    9,ADVTHREE
         B     ADV220
ADV240   LA    10,ADVCODE
         AR    10,9
         MVC   0(1,3),0(10)        '+', ' ', '0' or '-'
ADV300   PUT   (2),(3)             the line itself
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
ADVB3    DC    C'-'                a blank line that advances three
         DC    CL132' '
ADVCODE  DC    C'+ 0-'             0, 1, 2 or 3 lines
ADVONE   DC    H'1'
ADVPAGE  DC    H'999'              the page-skip request
ADVTHREE DC    H'3'
RTSAVE7  DS    18F
*
* COBUPSI -- set the eight switches from the EXEC PARM.
*
* PARM='/UPSI(10100000)' is the form IBM's later compilers
* take, and the one the runtime looks for: the literal UPSI
* anywhere in the parameter text, then the next eight 0 or 1
* characters, leftmost being UPSI-0. Anything else leaves all
* eight off, which is the documented default.
COBUPSI  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE6+4
         LA    11,RTSAVE6
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(parameter text)
         LA    2,0(0,2)            drop the end-of-list bit
         XC    RTUPSI,RTUPSI       all off unless the PARM says otherwi
         LH    3,0(0,2)            its length
         LA    4,2(0,2)            the text itself
         CH    3,UPSIMIN           room for UPSI and eight digits?
         BL    UPSX
         SH    3,UPSIMIN
         LA    3,1(3)              positions worth trying
UPS10    CLC   0(4,4),UPSITAG
         BE    UPS15
         LA    4,1(4)
         BCT   3,UPS10
         B     UPSX                no UPSI in the parameter
UPS15    LA    4,4(4)              past the tag
         CLI   0(4),C'0'
         BE    UPS20
         CLI   0(4),C'1'
         BE    UPS20
         LA    4,1(4)              skip a ( or an =
UPS20    SR    5,5                 the byte being built
         LA    6,8                 eight of them
UPS30    SLL   5,1
         CLI   0(4),C'1'
         BNE   UPS40
         LA    5,1(5)
UPS40    LA    4,1(4)
         BCT   6,UPS30
         ST    5,RTUPSI            the byte, for the caller to store
UPSX     L     13,4(13)
         L     15,RTUPSI           the byte, while R12 is still ours
         ST    15,16(13)           into the save area's R15 slot
         LM    14,12,12(13)
         BR    14
*
* COBACC -- one transfer from SYSIN into the caller's item.
*
* General rule 2 on II-53 leaves the size of a transfer to the
* implementor: here it is one 80-column record. The buffer is
* blanked first, so a receiver wider than a card is padded and
* a read past the last card returns spaces rather than the
* card before it.
*
* Parameter list: A(item), A(halfword length).
COBACC   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE5+4
         LA    11,RTSAVE5
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(item)
         L     3,4(0,1)            A(length)
         LH    4,0(0,3)            length
         MVI   ACCBUF,C' '
         MVC   ACCBUF+1(255),ACCBUF  blank the buffer
         CLI   ACCEOFF,X'01'       already at end of file?
         BE    COBA020
         CLI   ACCOPEN,X'01'       already open?
         BE    COBA010
         OPEN  (ACCDCB,INPUT)
         MVI   ACCOPEN,X'01'
COBA010  LA    1,COBA030
         STCM  1,7,ACCDCB+33       into DCBEODAD
         GET   ACCDCB,ACCBUF       one card
         B     COBA020
COBA030  MVI   ACCEOFF,X'01'       end of file: the buffer stays blank
COBA020  LTR   4,4
         BNP   COBA040             nothing to store
         CH    4,ACCMAX
         BNH   COBA035
         LH    4,ACCMAX            one MVC is 256 bytes
COBA035  BCTR  4,0                 EX wants length-1
         EX    4,COBAMVC
COBA040  L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
COBAMVC  MVC   0(0,2),ACCBUF       patched by EX
*
* COBTERM -- close SYSOUT if COBDISP ever opened it.
*
COBTERM  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE2+4
         LA    11,RTSAVE2
         ST    11,8(13)
         LR    13,11
         CLI   ACCOPEN,X'01'
         BNE   COBT005
         CLOSE (ACCDCB)
         MVI   ACCOPEN,X'00'
COBT005  CLI   RTOPEN,X'01'
         BNE   COBT010
         CLOSE (RTDCB)
         MVI   RTOPEN,X'00'
COBT010  L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
*
* COBDATE -- fill an 8-byte field with MM/DD/YY.
*   R1 -> the field.  TIME DEC hands back the date as packed
*   00YYDDDF, which is Julian, so the day of year has to be
*   walked into a month and a day.
*
COBDATE  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE4+4
         LA    11,RTSAVE4
         ST    11,8(13)
         LR    13,11
         LR    2,1                 the field, before TIME takes R1
         TIME  DEC                 R0 = HHMMSSth, R1 = 00YYDDDF
         ST    1,DTPACK
         UNPK  DTZONE(7),DTPACK(4)  '00YYDDD'
         OI    DTZONE+6,X'F0'
         PACK  DTDW(8),DTZONE+4(3)
         CVB   3,DTDW              day of the year
         PACK  DTDW(8),DTZONE+2(2)
         CVB   4,DTDW              the year
         N     4,DTF3              zero if a leap year -- 1901-2099, so
*                             mod 4 is the whole rule
         LA    5,1                 month
         LA    6,DTMON
DT010    SR    7,7
         IC    7,0(0,6)            days in this month
         CH    5,DTH2              February?
         BNE   DT020
         LTR   4,4
         BNZ   DT020
         LA    7,1(0,7)            29 this year
DT020    CR    3,7
         BNH   DT030               the day falls in this month
         SR    3,7
         LA    5,1(0,5)
         LA    6,1(0,6)
         B     DT010
DT030    CVD   5,DTDW
         UNPK  0(2,2),DTDW+6(2)    MM
         OI    1(2),X'F0'
         MVI   2(2),C'/'
         CVD   3,DTDW
         UNPK  3(2,2),DTDW+6(2)    DD
         OI    4(2),X'F0'
         MVI   5(2),C'/'
         MVC   6(2,2),DTZONE+2     YY, already zoned
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
DTMON    DC    AL1(31,28,31,30,31,30,31,31,30,31,30,31)
DTF3     DC    F'3'
DTH2     DC    H'2'
DTPACK   DS    F
DTZONE   DS    CL8
DTDW     DS    D
RTSAVE4  DS    18F
*
* COBWRL -- advance the paper and write one report line.
*   R1 -> A(dcb), A(current line), A(target line), A(buffer)
*
COBWRL   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE3+4
         LA    11,RTSAVE3
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(dcb)
         L     3,4(0,1)            A(current line)
         L     4,8(0,1)            A(target line)
         L     5,12(0,1)           A(buffer)
         LH    6,0(0,3)
         LH    7,0(0,4)
COBW010  LA    8,1(0,6)
         CR    8,7                 already at the line before the targe
         BNL   COBW020
         PUT   (2),RTBLNK          skip a line
         LA    6,1(0,6)
         B     COBW010
COBW020  PUT   (2),(5)
         STH   7,0(0,3)            current line = target
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
RTBLNK   DC    CL133' '            a blank line, ASA single space
RTSAVE3  DS    18F
RTOPEN   DC    X'00'
RTMAX    DC    H'120'
RTLINE   DC    CL121' '            ASA byte + 120 columns
RTSAVE1  DS    18F
RTSAVE2  DS    18F
RTSAVE5  DS    18F
RTSAVE6  DS    18F
RTUPSI   DS    F
UPSITAG  DC    C'UPSI'
UPSIMIN  DC    H'12'               UPSI, a bracket, eight digits
ACCOPEN  DC    X'00'
ACCEOFF  DC    X'00'
ACCBUF   DC    CL256' '            one card from SYSIN, blank padded
ACCMAX   DC    H'256'
ACCDCB   DCB   DDNAME=SYSIN,DSORG=PS,MACRF=(GM),                       X
               EODAD=0
RTDCB    DCB   DDNAME=SYSOUT,DSORG=PS,MACRF=(PM),RECFM=FBA,            X
               LRECL=121,BLKSIZE=121
         END
